import java.util.concurrent.ConcurrentHashMap;
import java.util.concurrent.atomic.LongAdder;
import java.util.Map;

public static Map<String, Long> countWordsConcurrently(Iterable<String> words) {
    ConcurrentHashMap<String, LongAdder> counts = new ConcurrentHashMap<>();
    words.forEach(word ->
        counts.computeIfAbsent(word.toLowerCase(Locale.ROOT), k -> new LongAdder())
              .increment()
    );
    Map<String, Long> result = new HashMap<>();
    counts.forEach((word, count) -> result.put(word, count.sum()));
    return result;
}

public static boolean isIsomorphic(String s, String t) {
    if (s.length() != t.length()) return false;
    Map<Character, Character> forward = new HashMap<>();
    Map<Character, Character> reverse = new HashMap<>();
    for (int i = 0; i < s.length(); i++) {
        char a = s.charAt(i), b = t.charAt(i);
        if (forward.containsKey(a) && forward.get(a) != b) return false;
        if (reverse.containsKey(b) && reverse.get(b) != a) return false;
        forward.put(a, b);
        reverse.put(b, a);
    }
    return true;
}

public static int longestSubarraySumK(int[] nums, int k) {
    Map<Long, Integer> firstIndex = new HashMap<>();
    firstIndex.put(0L, -1);
    long prefix = 0;
    int best = 0;
    for (int i = 0; i < nums.length; i++) {
        prefix += nums[i];
        firstIndex.putIfAbsent(prefix, i);
        Integer start = firstIndex.get(prefix - k);
        if (start != null) best = Math.max(best, i - start);
    }
    return best;
}

public static boolean searchMatrix(int[][] matrix, int target) {
    if (matrix == null || matrix.length == 0 || matrix[0].length == 0) return false;
    int row = 0, col = matrix[0].length - 1;
    while (row < matrix.length && col >= 0) {
        int value = matrix[row][col];
        if (value == target) return true;
        if (value > target) col--;
        else row++;
    }
    return false;
}

static class Node {
    int value;
    Node next;
    Node(int value) { this.value = value; }
}

public static Node mergeSortedLists(Node a, Node b) {
    Node dummy = new Node(0);
    Node tail = dummy;
    while (a != null && b != null) {
        if (a.value <= b.value) {
            tail.next = a;
            a = a.next;
        } else {
            tail.next = b;
            b = b.next;
        }
        tail = tail.next;
    }
    tail.next = (a != null) ? a : b;
    return dummy.next;
}

public static int minCoins(int[] coins, int amount) {
    if (amount < 0) return -1;
    int unreachable = amount + 1;
    int[] dp = new int[amount + 1];
    Arrays.fill(dp, unreachable);
    dp[0] = 0;
    for (int value = 1; value <= amount; value++) {
        for (int coin : coins) {
            if (coin > 0 && coin <= value && dp[value - coin] != unreachable) {
                dp[value] = Math.min(dp[value], dp[value - coin] + 1);
            }
        }
    }
    return dp[amount] == unreachable ? -1 : dp[amount];
}

Map<Boolean, List<Employee>> partitionBySalary(
        List<Employee> employees, BigDecimal threshold) {
    return employees.stream()
        .collect(Collectors.partitioningBy(
            e -> e.getSalary().compareTo(threshold) >= 0
        ));
}

public static boolean hasBalancedBrackets(String s) {
    Deque<Character> stack = new ArrayDeque<>();
    for (char c : s.toCharArray()) {
        if (c == '(' || c == '{' || c == '[') {
            stack.push(c);
        } else if (c == ')' || c == '}' || c == ']') {
            if (stack.isEmpty()) return false;
            char open = stack.pop();
            if ((c == ')' && open != '(')
                    || (c == '}' && open != '{')
                    || (c == ']' && open != '[')) return false;
        }
    }
    return stack.isEmpty();
}

public static boolean isPowerOfTwo(int n) {
    return n > 0 && (n & (n - 1)) == 0;
}
